const updateAgentHandler = async (req, res) => {
  const id = req.params.id;
  const validatedData = agentUpdateSchema.parse(req.body);
  const updateData = removeNullishValues(validatedData);
  if (includesStatefulConfiguration || includesToolsConfiguration) {
    existingAgent = await db.getAgent({ id });
    if (!existingAgent) return res.status(404).json({ error: 'Agent not found' });
  }
  const agent = await db.updateAgent({ id }, updateData);
