const addPromptToGroup = async (req, res) => {
  const { groupId } = req.params; const { prompt } = req.body;
  if (!prompt) return res.status(400);
  if (typeof prompt.prompt !== 'string' || !prompt.prompt.trim()) return res.status(400);
  if (prompt.type !== 'text' && prompt.type !== 'chat') return res.status(400);
  prompt.groupId = groupId;
  const saveData = { prompt, author: req.user.id, authorName: req.user.name };
  const result = await savePrompt(saveData);
  res.status(200).send(result);
}

async function createUser(data, balanceConfig, disableTTL=true, returnUser=false) {
  const userData = { ...data, expiresAt: disableTTL ? undefined : new Date(Date.now()+604800*1000) };
  const user = await User.create(userData);
  if (balanceConfig?.enabled && balanceConfig?.startBalance) { await Balance.findOneAndUpdate({user:user._id},{$inc:{tokenCredits:balanceConfig.startBalance}},{upsert:true,new:true}); }
  return returnUser ? user.toObject() : user._id;
}
